// Normalise the incoming quote-form payload into exactly one ledger row.
// Keys must match templates/ledger-schema.md verbatim: the Sheets append
// maps them to the header row by name, so extra or nested keys break it.
const b = $json.body || {};
const now = new Date();
const mel = { timeZone: 'Australia/Melbourne' };
const received = now.toLocaleString('en-AU', { ...mel, hour12: false });
const leadId = 'KL-' + Math.floor(now.getTime() / 1000).toString(36).toUpperCase();
// Grace window: the owner gets first go. Business days only.
const GRACE_DAYS = 5;
const d = new Date(now);
let added = 0;
while (added < GRACE_DAYS) {
  d.setDate(d.getDate() + 1);
  const day = d.getDay();
  if (day !== 0 && day !== 6) added++;
}
const graceEnds = d.toLocaleDateString('en-AU', mel);
const s = (v) => (v == null ? '' : String(v).slice(0, 2000));
return [{ json: {
  lead_id: leadId,
  received_at: received,
  source: s(b.source) || 'form',
  name: s(b.name),
  phone: s(b.phone),
  email: s(b.email),
  suburb: s(b.suburb),
  service: s(b.service),
  trees: s(b.trees),
  urgency: s(b.urgency),
  notes: s(b.notes),
  photos: s(b.photoCount || 0),
  page: s(b.page),
  status: 'new',
  grace_ends: graceEnds,
  billable_event: '',
  amount: '',
  billed_month: '',
  disputed: '',
  job_completed_at: '',
  service_cycle_months: '',
  last_touch: received
} }];
